const { spawnSync } = require('node:child_process');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const moduleFile = "src/slugify.js";
const testFile = "test/slugify.test.js";
const mutants = [[".toLowerCase()",""],["[^a-z0-9]+","[^a-z0-9]"],["/^-+|-+$/g","/^$/g"],["[^a-z0-9]+","[^a-z]+"]];
const root = process.cwd();
const run = (dir) => spawnSync(process.execPath, ['--test', testFile], { cwd: dir, stdio: 'ignore' }).status;
if (!fs.existsSync(path.join(root, testFile))) { console.error('missing ' + testFile); process.exit(1); }
if (run(root) !== 0) { console.error('the tests fail on the real module'); process.exit(1); }
const source = fs.readFileSync(path.join(root, moduleFile), 'utf8');
let survived = 0;
for (const [from, to] of mutants) {
  if (!source.includes(from)) { console.error('mutant not applicable: ' + from); process.exit(2); }
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'mutant-'));
  fs.cpSync(root, dir, { recursive: true });
  fs.writeFileSync(path.join(dir, moduleFile), source.replace(from, to));
  if (run(dir) === 0) { console.error('survived: ' + from); survived += 1; }
  fs.rmSync(dir, { recursive: true, force: true });
}
process.exit(survived === 0 ? 0 : 1);

