const fs = require('node:fs');
const readme = fs.readFileSync('README.md', 'utf8');
const names = Object.keys(require(process.cwd() + '/src/index.js'));
const missing = names.filter((name) => !readme.includes(`### \`${name}\``));
if (missing.length > 0) { console.error('README.md has no section for: ' + missing.join(', ')); process.exit(1); }

const fs = require('node:fs');
const readme = fs.readFileSync('README.md', 'utf8').split('\n');
const { DEFAULTS } = require(process.cwd() + '/src/truncate.js');
const missing = Object.entries(DEFAULTS).filter(([key, value]) => !readme.some((line) => line.startsWith(`| \`${key}\` |`) && line.includes(`\`${JSON.stringify(value)}\``)));
if (missing.length > 0) { console.error('README.md has no table row with the default of: ' + missing.map(([key]) => key).join(', ')); process.exit(1); }

